# Only Yices' own API leaves libyices.so.
#
# Yices links GMP statically (--with-static-gmp), so without this the shared
# library exports ~72 GMP symbols of its own. Together with the copy Camada
# absorbs and any real libgmp.so in the process, that leaves several
# definitions of __gmpz_init and lets load order decide which one callers bind
# to. Keeping GMP private to Yices removes it as a competing provider.
{
  global:
    yices_*;
  local:
    *;
};
